using System.Text;
using System.Threading.Tasks;

namespace GenDyn;

/// <summary>
/// 从 FunctionInfo 列表生成各语言代码
/// </summary>
public class CodeGenerator
{
    private readonly string _libName;
    private readonly string _dllName;
    private readonly List<FunctionInfo> _functions;

    public CodeGenerator(string libName, string dllName, List<FunctionInfo> functions)
    {
        _libName = libName;
        _dllName = dllName;
        _functions = functions;
    }

    public void GenerateVmlOnly(string outputDir)
    {
        Directory.CreateDirectory(outputDir);
        GenerateVmlWrapper(Path.Combine(outputDir, $"{_libName}.vml"));
    }

    public void GenerateCGlueOnly(string outputDir)
    {
        Directory.CreateDirectory(outputDir);
        GenerateCGlue(Path.Combine(outputDir, $"{_libName}_lib.c"));
    }

    /// <summary>生成语言绑定 → Lib/{lang}/ext/lib{name}.{ext}</summary>
    public void GenerateLanguageHeadersOnly(string libRoot, string[] targets)
    {
        GenerateAllLanguageHeaders(libRoot, targets);
    }

    // ============================================================
    // C 胶水代码
    // ============================================================
    private void GenerateCGlue(string path)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"/* {_libName}_lib.c — Auto-generated by GenDyn */");
        sb.AppendLine($"/* 编译 (Windows MSVC): cl /nologo /O2 /MD /LD /Fe:{_libName}.dll {_libName}_lib.c */");
        sb.AppendLine($"/* 编译 (macOS):        cc -shared -o lib{_libName}.dylib {_libName}_lib.c */");
        sb.AppendLine($"/* 编译 (Linux):        cc -shared -o lib{_libName}.so {_libName}_lib.c */");
        sb.AppendLine();
        sb.AppendLine("#ifdef _WIN32");
        sb.AppendLine("#include <windows.h>");
        sb.AppendLine("#else");
        sb.AppendLine("#include <dlfcn.h>");
        sb.AppendLine("#endif");
        sb.AppendLine("#include <stdio.h>");
        sb.AppendLine();
        sb.AppendLine("#ifndef _WIN32");
        sb.AppendLine("#define __stdcall");
        sb.AppendLine("#endif");
        sb.AppendLine();
        sb.AppendLine("#ifdef _WIN32");
        sb.AppendLine($"static HMODULE _target_dll = NULL;");
        sb.AppendLine("#else");
        sb.AppendLine("static void* _target_dll = NULL;");
        sb.AppendLine("#endif");
        // Derive platform-appropriate library name (strip .dll/.so/.dylib extension)
        var baseName = _dllName;
        if (baseName.EndsWith(".dll", StringComparison.OrdinalIgnoreCase))
            baseName = baseName[..^4];
        else if (baseName.EndsWith(".dylib", StringComparison.OrdinalIgnoreCase))
            baseName = baseName[..^6];
        else if (baseName.EndsWith(".so", StringComparison.OrdinalIgnoreCase))
            baseName = baseName[..^3];
        var dllName = baseName + ".dll";
        var dylibName = baseName + ".dylib";
        var soName = baseName + ".so";
        sb.AppendLine("#ifdef __APPLE__");
        sb.AppendLine($"static const char* _target_name = \"{dylibName}\";");
        sb.AppendLine("#elif defined(__linux__)");
        sb.AppendLine($"static const char* _target_name = \"{soName}\";");
        sb.AppendLine("#else");
        sb.AppendLine($"static const char* _target_name = \"{dllName}\";");
        sb.AppendLine("#endif");
        sb.AppendLine();

        sb.AppendLine("static void* _load_func(const char* name) {");
        sb.AppendLine("#ifdef _WIN32");
        sb.AppendLine("    if (!_target_dll) _target_dll = LoadLibraryA(_target_name);");
        sb.AppendLine("    if (!_target_dll) { fprintf(stderr, \"Cannot load %s\\n\", _target_name); return NULL; }");
        sb.AppendLine("    return (void*)GetProcAddress(_target_dll, name);");
        sb.AppendLine("#else");
        sb.AppendLine("    if (!_target_dll) _target_dll = dlopen(_target_name, RTLD_LAZY);");
        sb.AppendLine("    if (!_target_dll) { fprintf(stderr, \"Cannot load %s\\n\", _target_name); return NULL; }");
        sb.AppendLine("    return dlsym(_target_dll, name);");
        sb.AppendLine("#endif");
        sb.AppendLine("}");
        sb.AppendLine();

        foreach (var func in _functions)
        {
            var retType = CTypeStr(func.ReturnType);
            var paramList = string.Join(", ",
                func.Params.Select(p => $"{CTypeStr(p.Type)} {p.Name}"));
            var callArgs = string.Join(", ", func.Params.Select(p => p.Name));

            sb.AppendLine($"#ifdef _WIN32");
            sb.AppendLine($"__declspec(dllexport)");
            sb.AppendLine($"#endif");
            sb.AppendLine($"{retType} __stdcall {func.Name}({paramList})");
            sb.AppendLine("{");
            sb.AppendLine($"    typedef {retType} (__stdcall *fn_t)({paramList});");
            sb.AppendLine($"    static fn_t _fn = NULL;");
            sb.AppendLine($"    if (!_fn) _fn = (fn_t)_load_func(\"{func.OriginalName}\");");
            if (func.ReturnType == ParamType.Void) {
                sb.AppendLine("    if (!_fn) return;");
                sb.AppendLine($"    _fn({callArgs});");
            } else {
                sb.AppendLine("    if (!_fn) return 0;");
                sb.AppendLine($"    return _fn({callArgs});");
            }
            sb.AppendLine("}");
            sb.AppendLine();
        }

        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [C 胶水] {path}");
    }

    // ============================================================
    // VML 封装
    // ============================================================
    private void GenerateVmlWrapper(string path)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"; {_libName}.vml — Auto-generated by GenDyn");
        sb.AppendLine($"; 为 {_dllName} 中的 {_functions.Count} 个导出函数提供 FFI 封装");
        sb.AppendLine();
        sb.AppendLine("; === 内部状态 (固定内存地址) ===");
        sb.AppendLine("; [0xE000] = lib handle");
        sb.AppendLine("; [0xE010] = func_id 起始地址 (每个函数占 4 字节)");
        sb.AppendLine("; [0xE100] = 参数缓冲区");
        sb.AppendLine("; [0xE200] = 初始化标志");
        sb.AppendLine();

        // 入口: dl_open (用 DLL handle 自身作为已初始化标志)
        sb.AppendLine($".entry {_libName}_init");
        sb.AppendLine($"{_libName}_init:");
        sb.AppendLine("    ; 用 DLL handle [0xE000] 非零判断已初始化");
        sb.AppendLine("    LOAD R0, [0xE000]");
        sb.AppendLine("    LOAD R1, #0");
        sb.AppendLine("    CMP R0, R1");
        sb.AppendLine("    JNZ init_done");
        sb.AppendLine();
        sb.AppendLine($"    ; dl_open(\"{_libName}\")");
        sb.AppendLine("    LOAD R0, lib_path");
        sb.AppendLine("    SYSCALL #370");
        sb.AppendLine("    CMP R0, #0");
        sb.AppendLine("    JGE dl_ok");
        sb.AppendLine("    ; dlopen 失败, 不存储错误码, 下次调用时重试");
        sb.AppendLine("    JMP init_done");
        sb.AppendLine("dl_ok:");
        sb.AppendLine("    LOAD R12, #0xE000");
        sb.AppendLine("    STORE [R12], R0");
        sb.AppendLine();

        // 为每个函数 dl_sym
        int funcBase = 0xE010;
        for (int i = 0; i < _functions.Count; i++)
        {
            var func = _functions[i];
            int addr = funcBase + i * 4;
            sb.AppendLine($"    ; dl_sym: {func.Name}");
            sb.AppendLine($"    LOAD R0, [0xE000]");
            sb.AppendLine($"    LOAD R1, name_{func.Name}");
            sb.AppendLine("    SYSCALL #371");
            sb.AppendLine($"    LOAD R12, #0x{addr:X4}");
            sb.AppendLine("    STORE [R12], R0");
            sb.AppendLine();
        }

        sb.AppendLine("init_done:");
        sb.AppendLine("    RET");
        sb.AppendLine();

        // 每个函数的调用封装 — 统一走 NativeCallEx (SYSCALL #376)
        for (int i = 0; i < _functions.Count; i++)
        {
            var func = _functions[i];
            int funcAddr = funcBase + i * 4;
            int argsAddr = 0xE100;
            int typeDescAddr = 0xE200;

            sb.AppendLine($"; --- {func.Name}({string.Join(", ", func.Params.Select(p => p.Name))}) ---");
            GenerateNativeCallExWrapper(sb, func, funcAddr, argsAddr, typeDescAddr);
            sb.AppendLine();
        }

        // teardown
        sb.AppendLine($"; --- {_libName}_teardown ---");
        sb.AppendLine($"{_libName}_teardown:");
        sb.AppendLine("    LOAD R0, [0xE000]");
        sb.AppendLine("    SYSCALL #372");
        sb.AppendLine("    LOAD R0, #0");
        sb.AppendLine("    LOAD R12, #0xE000");
        sb.AppendLine("    STORE [R12], R0");
        sb.AppendLine("    RET");
        sb.AppendLine();

        // 字符串常量 (lib_path 从 DLL 文件名派生, 确保 DLOpen 找到正确的文件)
        sb.AppendLine("; === 字符串常量 ===");
        sb.AppendLine("lib_path:");
        string dllBaseName = Path.GetFileNameWithoutExtension(_dllName);
        sb.AppendLine($"    .string \"{dllBaseName}\"");
        foreach (var func in _functions)
        {
            sb.AppendLine($"name_{func.Name}:");
            sb.AppendLine($"    .string \"{func.OriginalName}\"");
        }
        sb.AppendLine();
        sb.AppendLine(".stack 4096");

        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [VML 封装] {path}");
    }

    /// <summary>
    /// 生成 NativeCallEx (SYSCALL #376) VML 封装: 栈传参 + 被调用方清理 (cdecl 语义)
    /// C/C++/ObjC 统一使用 cdecl: 调用者右到左 PUSH, wrapper 负责清理
    /// </summary>
    private void GenerateNativeCallExWrapper(StringBuilder sb, FunctionInfo func,
        int funcAddr, int argsAddr, int typeDescAddr)
    {
        int argCount = func.Params.Count;

        // 计算栈上参数总字节数 + 预计算每个参数在 args 缓冲区中的紧凑偏移
        int totalStackBytes = 0;
        int[] paramBufOffset = new int[argCount]; // 紧凑连续偏移 (运行时按连续字节流读取)
        for (int j = 0; j < argCount; j++)
        {
            var param = func.Params[j];
            paramBufOffset[j] = totalStackBytes;
            int sz = param.Type == ParamType.Struct
                ? ((param.StructSize > 0 ? param.StructSize : 4) + 3) / 4 * 4
                : 4;
            totalStackBytes += sz;
        }

        // 别名标签: 多语言支持 (Ladder/Forth/BASIC/Pascal/Function 前缀)
        sb.AppendLine($"LADDER_{func.Name.ToUpper()}:");
        sb.AppendLine($"word_{func.Name}:");
        sb.AppendLine($"method_{func.Name}:");
        sb.AppendLine($"sub_{func.Name}:");
        sb.AppendLine($"func_{func.Name}:");
        sb.AppendLine($"{func.Name}:");
        sb.AppendLine("    ; cdecl: 调用者右到左 PUSH params, wrapper 负责清理");

        // 保存 BP (R12), _init 会破坏 R12
        sb.AppendLine($"    LOAD R10, #0x{0xE300:X4}");
        sb.AppendLine($"    STORE [R10], R12  ; 保存调用者的 BP");

        // 阶段1: 从栈读取参数到 args 缓冲区 (紧凑连续布局)
        // cdecl 调用者 PUSH 顺序: 右到左 (paramN-1, paramN-2, ..., param0)
        // 栈顶 [R13+4] = 最后入栈的参数 = param0 (第1个参数)
        int stackOff = 4; // [R13+0] = CALL 压入的返回地址, 参数从 [R13+4] 开始
        for (int j = 0; j < argCount; j++)
        {
            var param = func.Params[j];
            if (param.Type == ParamType.Struct)
            {
                int structSize = param.StructSize > 0 ? param.StructSize : 4;
                int numWords = (structSize + 3) / 4;
                for (int w = 0; w < numWords; w++)
                {
                    sb.AppendLine($"    LOAD R10, [R13+#{stackOff}]      ; {param.Name} word {w}");
                    sb.AppendLine($"    LOAD R11, #0x{argsAddr + paramBufOffset[j] + w * 4:X4}");
                    sb.AppendLine($"    STORE [R11], R10");
                    stackOff += 4;
                }
            }
            else
            {
                sb.AppendLine($"    LOAD R10, [R13+#{stackOff}]      ; {param.Name}");
                sb.AppendLine($"    LOAD R11, #0x{argsAddr + paramBufOffset[j]:X4}");
                sb.AppendLine($"    STORE [R11], R10");
                stackOff += 4;
            }
        }
        // stackOff 现在 == 4 + totalStackBytes

        sb.AppendLine("    PUSH R15");
        sb.AppendLine($"    CALL {_libName}_init");
        sb.AppendLine("    POP R15");

        // 阶段2: 写类型描述符
        for (int j = 0; j < argCount; j++)
        {
            var param = func.Params[j];
            int typeCode = param.FfiTypeCode;
            int structSize = param.StructSize;
            int typeWord = typeCode | (structSize << 8);
            sb.AppendLine($"    LOAD R11, #0x{typeDescAddr + j * 4:X4}");
            sb.AppendLine($"    LOAD R10, #0x{typeWord:X8}     ; FFI type {param.Type}");
            sb.AppendLine("    STORE [R11], R10");
        }

        // 阶段3: SYSCALL #376
        sb.AppendLine($"    LOAD R0, [0x{funcAddr:X4}]");
        sb.AppendLine($"    LOAD R1, #0x{argsAddr:X4}");
        sb.AppendLine($"    LOAD R2, #0x{typeDescAddr:X4}");
        sb.AppendLine($"    LOAD R3, #{argCount}");
        sb.AppendLine($"    LOAD R4, #{func.RetFfiTypeCode}");
        sb.AppendLine("    SYSCALL #376");

        // 阶段4: cdecl — 调用者清理栈, wrapper 只负责恢复 BP 并返回
        // 不需要 ADD R13,#N (那是调用者的责任)
        // 恢复 BP
        sb.AppendLine($"    LOAD R12, [0x{0xE300:X4}]  ; 恢复调用者的 BP");
        sb.AppendLine("    RET");
    }

    // ============================================================
    // 22 语言头文件
    // ============================================================
    private void GenerateAllLanguageHeaders(string libRoot, string[] targets)
    {
        string pascalClass = PascalCaseName(_libName);
        Parallel.ForEach(targets, lang =>
        {
            switch (lang)
            {
                case "c":
                    GenerateCLangHeader(Path.Combine(libRoot, "c", "ext", $"lib{_libName}.h"));
                    break;
                case "cpp":
                    GenerateCppHeader(Path.Combine(libRoot, "cpp", "ext", $"lib{_libName}.hpp"));
                    break;
                case "basic":
                    GenerateBasicHeader(Path.Combine(libRoot, "basic", "ext", $"lib{_libName}.bas"));
                    break;
                case "pascal":
                    GeneratePascalHeader(Path.Combine(libRoot, "pascal", "ext", $"lib{_libName}.pas"));
                    break;
                case "python":
                    GeneratePythonHeader(Path.Combine(libRoot, "python", "ext", $"lib{_libName}.py"));
                    break;
                case "lua":
                    GenerateLuaHeader(Path.Combine(libRoot, "lua", "ext", $"lib{_libName}.lua"));
                    break;
                case "forth":
                    GenerateForthHeader(Path.Combine(libRoot, "forth", "ext", $"lib{_libName}.fth"));
                    break;
                case "rust":
                    GenerateRustHeader(Path.Combine(libRoot, "rust", "ext", $"lib{_libName}.rs"));
                    break;
                case "go":
                    GenerateGoHeader(Path.Combine(libRoot, "go", "ext", $"lib{_libName}.go"));
                    break;
                case "ladder":
                    GenerateLadderHeader(Path.Combine(libRoot, "ladder", "ext", $"lib{_libName}.ld"));
                    break;
                case "java":
                    GenerateJavaHeader(Path.Combine(libRoot, "java", "ext", $"Lib{pascalClass}.java"));
                    break;
                case "javascript":
                    GenerateJavaScriptHeader(Path.Combine(libRoot, "javascript", "ext", $"lib{_libName}.js"));
                    break;
                case "csharp":
                    GenerateCSharpHeader(Path.Combine(libRoot, "csharp", "ext", $"Lib{pascalClass}.cs"));
                    break;
                case "swift":
                    GenerateSwiftHeader(Path.Combine(libRoot, "swift", "ext", $"lib{_libName}.swift"));
                    break;
                case "kotlin":
                    GenerateKotlinHeader(Path.Combine(libRoot, "kotlin", "ext", $"lib{_libName}.kt"));
                    break;
                case "scheme":
                    GenerateSchemeHeader(Path.Combine(libRoot, "scheme", "ext", $"lib{_libName}.scm"));
                    break;
                case "ruby":
                    GenerateRubyHeader(Path.Combine(libRoot, "ruby", "ext", $"lib{_libName}.rb"));
                    break;
                case "dart":
                    GenerateDartHeader(Path.Combine(libRoot, "dart", "ext", $"lib{_libName}.dart"));
                    break;
                case "objc":
                    GenerateObjCHeader(Path.Combine(libRoot, "objc", "ext", $"lib{_libName}.h"));
                    break;
                case "r":
                    GenerateRHeader(Path.Combine(libRoot, "r", "ext", $"lib{_libName}.r"));
                    break;
                case "d":
                    GenerateDHeader(Path.Combine(libRoot, "d", "ext", $"lib{_libName}.d"));
                    break;
                case "fortran":
                    GenerateFortranHeader(Path.Combine(libRoot, "fortran", "ext", $"lib{_libName}.f90"));
                    break;
            }
        });
    }

    private void EnsureDir(string path)
    {
        var dir = Path.GetDirectoryName(path);
        if (dir != null) Directory.CreateDirectory(dir);
    }

    // --- C ---
    private void GenerateCLangHeader(string path)
    {
        EnsureDir(path);
        var sb = new StringBuilder();
        sb.AppendLine($"/* {_libName}.h - VML {_libName} FFI Bindings (C) */");
        sb.AppendLine($"/* Auto-generated by GenDyn */");
        sb.AppendLine($"#ifndef VML_EXT_{_libName.ToUpper()}_H");
        sb.AppendLine($"#define VML_EXT_{_libName.ToUpper()}_H");
        sb.AppendLine();
        sb.AppendLine($"#param lib(\"{_libName}\")");
        sb.AppendLine();
        foreach (var f in _functions)
            sb.AppendLine($"extern {CTypeStr(f.ReturnType)} {f.Name}({FormatCParams(f)});");
        sb.AppendLine();
        sb.AppendLine($"#endif /* VML_EXT_{_libName.ToUpper()}_H */");
        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [C 头文件] {path}");
    }

    // --- C++ ---
    private void GenerateCppHeader(string path)
    {
        EnsureDir(path);
        var sb = new StringBuilder();
        sb.AppendLine($"// {_libName}.hpp - VML {_libName} FFI Bindings (C++)");
        sb.AppendLine($"// Auto-generated by GenDyn");
        sb.AppendLine($"#pragma once");
        sb.AppendLine();
        sb.AppendLine($"#param lib(\"{_libName}\")");
        sb.AppendLine();
        sb.AppendLine("extern \"C\" {");
        foreach (var f in _functions)
            sb.AppendLine($"    {CTypeStr(f.ReturnType)} {f.Name}({FormatCParams(f)});");
        sb.AppendLine("}");
        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [C++ 头文件] {path}");
    }

    // --- BASIC ---
    private void GenerateBasicHeader(string path)
    {
        EnsureDir(path);
        var sb = new StringBuilder();
        sb.AppendLine($"' {_libName}.bas - VML {_libName} FFI Bindings (BASIC)");
        sb.AppendLine($"' Auto-generated by GenDyn");
        sb.AppendLine();
        foreach (var f in _functions)
        {
            var basicName = PascalCaseName(f.Name);
            if (f.ReturnType == ParamType.Void)
            {
                sb.AppendLine($"DECLARE SUB {basicName}({FormatBasicParams(f)})");
                sb.AppendLine("END SUB");
            }
            else
            {
                var ret = f.ReturnType switch
                {
                    ParamType.Float => "SINGLE",
                    ParamType.Float64 => "DOUBLE",
                    ParamType.Int64 => "LONG",
                    _ => "INTEGER"
                };
                sb.AppendLine($"DECLARE FUNCTION {basicName}({FormatBasicParams(f)}) AS {ret}");
                sb.AppendLine($"    {basicName} = 0");
                sb.AppendLine("END FUNCTION");
            }
            sb.AppendLine();
        }
        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [BASIC 头文件] {path}");
    }

    // --- Pascal ---
    private void GeneratePascalHeader(string path)
    {
        EnsureDir(path);
        var sb = new StringBuilder();
        sb.AppendLine($"{{ {_libName}.pas - VML {_libName} FFI Bindings (Pascal) }}");
        sb.AppendLine($"{{ Auto-generated by GenDyn }}");
        sb.AppendLine();
        sb.AppendLine("interface");
        sb.AppendLine();
        foreach (var f in _functions)
        {
            var ret = f.ReturnType == ParamType.Void ? "" :
                      f.ReturnType switch { ParamType.Float => ": real", ParamType.Float64 => ": double", ParamType.Int64 => ": int64", _ => ": integer" };
            sb.AppendLine($"function {f.Name}({FormatPascalParams(f)}){ret}; external;");
        }
        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [Pascal 头文件] {path}");
    }

    // --- Python ---
    private void GeneratePythonHeader(string path)
    {
        EnsureDir(path);
        var sb = new StringBuilder();
        sb.AppendLine($"# {_libName}.py - VML {_libName} FFI Bindings (Python)");
        sb.AppendLine($"# Auto-generated by GenDyn");
        sb.AppendLine();
        sb.AppendLine($"# from ext.{_libName} import *");
        sb.AppendLine();
        foreach (var f in _functions)
        {
            var ret = f.ReturnType == ParamType.Void ? "None" :
                      f.ReturnType == ParamType.Float ? "float" :
                      f.ReturnType == ParamType.Float64 ? "float" :
                      f.ReturnType == ParamType.Int64 ? "int" : "int";
            sb.AppendLine($"def {f.Name}({FormatPythonParams(f)}) -> {ret}:");
            sb.AppendLine("    pass  # ffi call");
            sb.AppendLine();
        }
        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [Python 头文件] {path}");
    }

    // --- Lua ---
    private void GenerateLuaHeader(string path)
    {
        EnsureDir(path);
        var sb = new StringBuilder();
        sb.AppendLine($"-- {_libName}.lua - VML {_libName} FFI Bindings (Lua)");
        sb.AppendLine($"-- Auto-generated by GenDyn");
        sb.AppendLine();
        foreach (var f in _functions)
        {
            var ret = f.ReturnType == ParamType.Void ? "" :
                      f.ReturnType == ParamType.Float ? " -> float" :
                      f.ReturnType == ParamType.Float64 ? " -> double" :
                      f.ReturnType == ParamType.Int64 ? " -> long" : " -> int";
            sb.AppendLine($"-- function {f.Name}({FormatPyParams(f)}){ret}");
        }
        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [Lua 头文件] {path}");
    }

    // --- Forth ---
    private void GenerateForthHeader(string path)
    {
        EnsureDir(path);
        var sb = new StringBuilder();
        sb.AppendLine($"\\ {_libName}.fth - VML {_libName} FFI Bindings (Forth)");
        sb.AppendLine($"\\ Auto-generated by GenDyn");
        sb.AppendLine();
        foreach (var f in _functions)
        {
            var ret = f.ReturnType == ParamType.Void ? " --" :
                      f.ReturnType == ParamType.Float ? " -- f" :
                      f.ReturnType == ParamType.Float64 ? " -- d" :
                      f.ReturnType == ParamType.Int64 ? " -- l" : " -- n";
            sb.AppendLine($"\\ {f.Name} ( {string.Join(" ", f.Params.Select(_ => "n"))}{ret} )");
        }
        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [Forth 头文件] {path}");
    }

    // --- Rust ---
    private void GenerateRustHeader(string path)
    {
        EnsureDir(path);
        var sb = new StringBuilder();
        sb.AppendLine($"// {_libName}.rs - VML {_libName} FFI Bindings (Rust)");
        sb.AppendLine($"// Auto-generated by GenDyn");
        sb.AppendLine();
        sb.AppendLine("extern \"C\" {");
        foreach (var f in _functions)
        {
            var ret = f.ReturnType == ParamType.Void ? "" :
                      f.ReturnType switch { ParamType.Float => " -> f32", ParamType.Float64 => " -> f64", ParamType.Int64 => " -> i64", _ => " -> i32" };
            var rparams = string.Join(", ", f.Params.Select(p =>
                p.Type switch
                {
                    ParamType.Float => $"{p.Name}: f32",
                    ParamType.Float64 => $"{p.Name}: f64",
                    ParamType.Int64 => $"{p.Name}: i64",
                    ParamType.String => $"{p.Name}: *const u8",
                    ParamType.Struct => $"{p.Name}: *mut core::ffi::c_void",
                    ParamType.StructPtr => $"{p.Name}: *mut core::ffi::c_void",
                    _ => $"{p.Name}: i32"
                }));
            sb.AppendLine($"    fn {f.Name}({rparams}){ret};");
        }
        sb.AppendLine("}");
        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [Rust 头文件] {path}");
    }

    // --- Go ---
    private void GenerateGoHeader(string path)
    {
        EnsureDir(path);
        var sb = new StringBuilder();
        sb.AppendLine($"// {_libName}.go - VML {_libName} FFI Bindings (Go)");
        sb.AppendLine($"// Auto-generated by GenDyn");
        sb.AppendLine();
        sb.AppendLine("package ext");
        sb.AppendLine();
        sb.AppendLine("/*");
        sb.AppendLine("#cgo LDFLAGS: -L../dynamic -l" + _libName);
        foreach (var f in _functions)
        {
            var ret = CTypeStr(f.ReturnType);
            sb.AppendLine($"{ret} {f.Name}({FormatCParams(f)});");
        }
        sb.AppendLine("*/");
        sb.AppendLine("import \"C\"");
        sb.AppendLine();
        foreach (var f in _functions)
        {
            var ret = f.ReturnType == ParamType.Void ? "" :
                      f.ReturnType switch { ParamType.Float => "float32", ParamType.Float64 => "float64", ParamType.Int64 => "int64", _ => "int" };
            sb.AppendLine($"func {PascalCaseName(f.Name)}({FormatGoParams(f)}) {ret} {{");
            if (f.ReturnType != ParamType.Void)
                sb.AppendLine($"    return C.{f.Name}({FormatGoCallArgs(f)})");
            else
                sb.AppendLine($"    C.{f.Name}({FormatGoCallArgs(f)})");
            sb.AppendLine("}");
            sb.AppendLine();
        }
        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [Go 头文件] {path}");
    }

