    private void GenerateFortranHeader(string path)
    {
        EnsureDir(path);
        var sb = new StringBuilder();
        sb.AppendLine($"! {_libName}.f90 - VML {_libName} FFI Bindings (Fortran)");
        sb.AppendLine($"! Auto-generated by GenDyn");
        sb.AppendLine();
        sb.AppendLine("interface");
        foreach (var f in _functions)
        {
            var ret = f.ReturnType == ParamType.Void ? "subroutine" :
                      f.ReturnType switch { ParamType.Float => "real function", ParamType.Float64 => "double precision function", _ => "integer function" };
            var fparams = string.Join(", ", f.Params.Select(p =>
                p.Type switch { ParamType.Float => $"real :: {p.Name}", ParamType.Float64 => $"double precision :: {p.Name}", ParamType.Int64 => $"integer(8) :: {p.Name}", _ => $"integer :: {p.Name}" }));
            if (f.ReturnType == ParamType.Void)
                sb.AppendLine($"    {ret} {f.Name}({fparams})");
            else
                sb.AppendLine($"    {ret} {f.Name}({fparams})");
        }
        sb.AppendLine("end interface");
        File.WriteAllText(path, sb.ToString());
        Console.WriteLine($"  [Fortran 头文件] {path}");
    }

    // ============================================================
    // 格式化辅助函数
    // ============================================================
    private static string CTypeStr(ParamType t) => t switch
    {
        ParamType.Float => "float",
        ParamType.Float64 => "double",
        ParamType.Void => "void",
        ParamType.String => "const char*",
        ParamType.Int64 => "long long",
        ParamType.Struct => "void*",
        ParamType.StructPtr => "void*",
        _ => "int"
    };

    private static string FormatCParams(FunctionInfo f)
    {
        if (f.Params.Count == 0) return "void";
        return string.Join(", ", f.Params.Select(p => $"{CTypeStr(p.Type)} {p.Name}"));
    }

    private static string LangTypeStr(ParamType t, string intName, string floatName,
        string doubleName, string longName, string stringName, string structName = "void*")
    {
        return t switch
        {
            ParamType.Float => floatName,
            ParamType.Float64 => doubleName,
            ParamType.Int64 => longName,
            ParamType.String => stringName,
            ParamType.Struct => structName,
            ParamType.StructPtr => structName,
            _ => intName
        };
    }

    private static string FormatBasicParams(FunctionInfo f)
    {
        return string.Join(", ", f.Params.Select(p =>
            $"BYVAL {p.Name} AS {LangTypeStr(p.Type, "INTEGER", "SINGLE", "DOUBLE", "LONG", "STRING", "INTEGER")}"));
    }

    private static string FormatPascalParams(FunctionInfo f)
    {
        return string.Join("; ", f.Params.Select(p =>
            $"{p.Name}: {LangTypeStr(p.Type, "integer", "real", "double", "int64", "string", "Pointer")}"));
    }

    private static string FormatPythonParams(FunctionInfo f)
    {
        return string.Join(", ", f.Params.Select(p =>
            $"{p.Name}: {LangTypeStr(p.Type, "int", "float", "float", "int", "str", "int")}"));
    }

    private static string FormatPyParams(FunctionInfo f)
    {
        return string.Join(", ", f.Params.Select(p => p.Name));
    }

    private static string FormatGoParams(FunctionInfo f)
    {
        return string.Join(", ", f.Params.Select(p =>
            $"{p.Name} {LangTypeStr(p.Type, "int", "float32", "float64", "int64", "string", "unsafe.Pointer")}"));
    }

    private static string FormatGoCallArgs(FunctionInfo f)
    {
        return string.Join(", ", f.Params.Select(p => p.Type switch
        {
            ParamType.Float => $"C.float({p.Name})",
            ParamType.Float64 => $"C.double({p.Name})",
            ParamType.Int64 => $"C.longlong({p.Name})",
            ParamType.String => $"C.CString({p.Name})",
            ParamType.Struct => $"unsafe.Pointer({p.Name})",
            ParamType.StructPtr => $"unsafe.Pointer({p.Name})",
            _ => $"C.int({p.Name})"
        }));
    }

    private static string FormatJavaParams(FunctionInfo f)
    {
        return string.Join(", ", f.Params.Select(p =>
            $"{LangTypeStr(p.Type, "int", "float", "double", "long", "String", "long")} {p.Name}"));
    }

    private static string FormatCSharpParams(FunctionInfo f)
    {
        return string.Join(", ", f.Params.Select(p =>
            $"{LangTypeStr(p.Type, "int", "float", "double", "long", "string", "IntPtr")} {p.Name}"));
    }

    private static string PascalCaseName(string name)
    {
        if (string.IsNullOrEmpty(name)) return name;
        // snake_case → PascalCase
        var parts = name.Split('_');
        return string.Join("", parts.Select(p =>
            p.Length > 0 ? char.ToUpper(p[0]) + p[1..] : ""));
    }
}
